function InvestPopup:__init()
    
end

function InvestPopup:__delete()
    if self.coShowAnima then
        cs_coroutine.stop(self.coShowAnima)
    end
    if self.effectLoaderTitle then
        self.effectLoaderTitle:Release(true)
        self.effectLoaderTitle = nil
    end
    if self.effectLoaderRole then
        self.effectLoaderRole:Release(true)
        self.effectLoaderRole = nil
    end
    self.effectGoTitle = nil
    self.effectGoRole = nil
    self.coShowAnima = nil
    self.roleId = nil
    self.listReward = nil
    self.pathImgShow =nil
    self.uiTemplate = nil
    self.firstPayState = nil
    self.canvasGroup = nil
    self.controller = nil
end

function InvestPopup:Awake()
    --self.controller.MarkPoolable = true
    Events.Broadcast(Constants.EventNames.MainHomeCameraSwip,  {isTrue = false})
end

function InvestPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local rootCG = self.controller.transform:Find("Container")
        self.canvasGroup = KTool.GetOrAddComponent(rootCG.gameObject, typeof(CanvasGroup)) 
        self.controller:SetBackArgument(true)
    end))
    return coWait
end

function InvestPopup:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:GetConfigData()
        self:InitComponent()
        local entryType = PlayerPrefsUtility.GetEncryptedBool(Constants.UICacheDataKeys.UI_INVEST_POP_ENTRY_TYPE, true)
        self.coShowAnima = cs_coroutine.start(function()
            self.Anima_Root.enabled = true
            local nameAnima = entryType and "Play" or "Empty"
            self.Anima_Root:Play(nameAnima)
        end)
        if entryType then
            local length = 0.16--CfUtils.GetAnimatorTime(self.Anima_Root.gameObject, "InvestPopup")
            self.coInitClose = cs_coroutine.start(function()
                cs_coroutine.yield_return(CS.Engine.Lib.Yielders.GetWaitForSeconds(checkNumber(length)))
                self:AniCompleted()
            end)
        else
            self:AniCompleted()
        end
    end))
    return coWait
end

function InvestPopup:OnFocus(focus)
    if focus then
        self:GetServersData()
        self:InitButton()
    end
    KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, focus)
end

function InvestPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        PlayerPrefsUtility.SetEncryptedBool(Constants.UICacheDataKeys.UI_INVEST_POP_ENTRY_TYPE, false)
        Events.Broadcast(Constants.EventNames.MainHomeCameraSwip,  {isTrue = true})
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

