function InvestPopup:GetServersData()
    self.firstPayState = 99
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if not IsNull(playerComp) then
        local playDJ = playerComp.playerDojo
        if not IsNull(playDJ) then
            self.firstPayState = playDJ.firstPay
        end
    end
end

function InvestPopup:AniCompleted()
    self:SetRoleInfo()
    self:SetPanelInteractable()
end

function InvestPopup:SetPanelInteractable()
    if not isNull(self.canvasGroup) then
        self.canvasGroup.blocksRaycasts = true
        self.canvasGroup.interactable = true
    end
end

function InvestPopup:InitFuncClosePanel()
    SetButtonAction(self.BtnClose.gameObject, function()
        self:PanelClose()
    end)
    KTool.GetOrAddComponent(self.ImgBg.gameObject, typeof(CS.Engine.UI.UIEventProxy)).onPointerClick = function()
        self:PanelClose()
    end
end

function InvestPopup:InitComponent()
    self:InitFuncClosePanel()
    self:InitRewardList(self.rewards, false) 
    self:SetShowImg()
    KTool.SetActive(self.BtnRoleNameNode, false)
end

function InvestPopup:InitButton()
    SetButtonAction(self.BtnLeaveforCharge.gameObject, function()
        local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
        blocker:AddCondition("__ExecuteJump")
        xTry(function ()
            cs_coroutine.start(function ()
                xRecord.record("9-015")
                ---@type PlayerComponent
                local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                local newPlayerActivityTime = checkNumber(playerComponent.playerDojo.rookieOpened)
                if checkInt(newPlayerActivityTime) > 0 then
                    GameUtils.Request(Interfaces.StoreRookieGift , {}, function(request, response)
                        if checkNumber(response.errCode) == 0 then
                            local data = response.data
                            local giftBag = data.giftBag
                            local isHave = false
                            --- 判断一下 是否有礼包可以购买
                            for i, v in pairs(giftBag) do
                                if checkInt(v.giftType) == 2 then
                                    if v.currentStock > 0  then
                                        isHave = true
                                        break
                                    end
                                end
                            end

                            if isHave then
                                local KCookie = CS.Engine.Lib.KCookie
                                KCookie.Set("BeginnerEventDialog", 4)
                                local t = {}
                                local dialogs = UIModule.CurrentScreen.dialogs
                                for _, dialog in pairs(dialogs) do
                                    --if checkNumber(dialog.Argument.id) ~= Constants.UITypeIds.UIFightTeamCardChoose and checkNumber(dialog.Argument.id) ~= 3720 then
                                    table.insert(t, dialog.Argument)
                                    --end
                                end
                                UIModule.OpenDialog(
                                        { id = Constants.UITypeIds.BeginnerEventDialog},
                                        t
                                )
                                blocker:RemoveCondition("__ExecuteJump")
                                return
                            end
                            ---@type StoreUtils
                            local storeUtils = import('Game.UI.Store.StoreUtils')
                            ---@type StoreConstants
                            local StoreConstants = import('Game.UI.Store.StoreConstants')
                            storeUtils.OpenStore(StoreConstants.OpenIds.Diamond, {{id = Constants.UITypeIds.InvestPopup}}, {hideToggle = true})
                            blocker:RemoveCondition("__ExecuteJump")
                        end
                    end)
                else
                    ---@type StoreUtils
                    local storeUtils = import('Game.UI.Store.StoreUtils')
                    ---@type StoreConstants
                    local StoreConstants = import('Game.UI.Store.StoreConstants')
                    storeUtils.OpenStore(StoreConstants.OpenIds.Diamond, {{id = Constants.UITypeIds.InvestPopup}}, {hideToggle = true})
                    blocker:RemoveCondition("__ExecuteJump")
                end
            end)
        end, function()
            print_to_file(debug.traceback())
            blocker:RemoveCondition("__ExecuteJump")
        end)
    end)
    SetButtonAction(self.BtnDrawn.gameObject,function()
        GameUtils.Request(Interfaces.PlayerDrawFirstPay, {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then return end
            local jsonData = response.data
            local rewardData = checkTable(jsonData.rewards)
            ---@type PlayerComponent
            local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            playerComp.playerDojo.firstPay = 3
            self:SyncSpringSale(playerComp,jsonData)
            self:PanelClose(rewardData) --管理界面
        end)
    end)
    KTool.SetActive(self.BtnDrawn.gameObject, self.firstPayState == 2)
    KTool.SetActive(self.BtnLeaveforCharge.gameObject, self.firstPayState == 1)
end
---这里要给主界面发送一下消息 通知一下首充完成 还要处理一下限时特惠的数据
function InvestPopup:SyncSpringSale(playerComp,jsonData)
    playerComp.playerDojo.continuousPayFinally = 0  --直接设置为不可领取
    playerComp.playerDojo.continuousPayPlay = true  ---首充完成 需要变为true
end

function InvestPopup:InitRewardList(data, isGet)
    if not isNull(self.CommonGoodsList) then
        self.CommonGoodsList:Init()
        self.listReward = self.CommonGoodsList.Env
        self.listReward:FreshBaseUI(data, nil, isGet)
    end
end

