---GetConfigData
---获取配表数据
function InvestPopup:GetConfigData()
    self.settingMgr = SettingMgr:GetInstance()
    ---@type TableML.TableFile
    local tableFile = self.settingMgr:Get(AutoIds.IdSetting1802)
    ---@type TableML.TableFileRow
    local rowData = tableFile:GetByPrimaryKey(tostring(1)) -- 配表第一行
    self.rewards = self:GetConfigReward(rowData) -- 奖励列表
    local ParseUtils = CS.ParseUtils
    self.pathImgShow = ParseUtils.ParsePathName(rowData, "showImage") -- 展示立绘
    self.uiTemplate = ParseUtils.ParsePathName(rowData, "template") -- 展示模板
    self.roleId = parse_number(rowData, "roleId") -- 奖励角色 ID
    self.rare = parse_number(rowData, "gradeImage") -- 稀有度
end

---GetConfigReward
---获取奖励列表
function InvestPopup:GetConfigReward(data)
    local strRewardIds = parse_string(data, "reward")
    local strRewardNums = parse_string(data, "rewardNum")
    local listRewardIds = string.split(strRewardIds, ";")
    local listRewardNums = string.split(strRewardNums,";")
    local tableResult = {}
    for i, value in ipairs(listRewardIds) do
        local rewardData = { goodsId = value, num = listRewardNums[i], }
        table.insert(tableResult, rewardData)
    end
    return tableResult
end

